import{c as o,Z as e,Q as i,j as l,m as r,o as u}from"./chunks/framework.DOi4mjdC.js";const _=JSON.parse('{"title":"寿阳曲·远浦帆归","description":"","frontmatter":{"title":"寿阳曲·远浦帆归","author":"马致远","dynasty":"元"},"headers":[],"relativePath":"books/shici/yuanqu/7.md","filePath":"books/shici/yuanqu/7.md"}'),n={name:"books/shici/yuanqu/7.md"};function s(h,a,q,p,c,d){const t=e("PoemNav");return i(),l("div",null,[a[0]||(a[0]=r('<h1 id="寿阳曲·远浦帆归" tabindex="-1">寿阳曲·远浦帆归 <a class="header-anchor" href="#寿阳曲·远浦帆归" aria-label="Permalink to &quot;寿阳曲·远浦帆归&quot;">​</a></h1><p><strong>[元] <a href="/authors/mazhiyuan.html">马致远</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>夕阳下，酒旆闲，两三航未曾着岸。落花水香茅舍晚，断桥头卖鱼人散。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>寿阳曲：曲牌名，又名&quot;落梅风&quot;</li><li>远浦：远处的水边</li><li>帆归：船帆归来，指渔船归港</li><li>酒旆：酒旗，酒店门前悬挂的旗帜</li><li>闲：悠闲地飘动</li><li>航：船</li><li>着岸：靠岸</li><li>落花水香：落花飘落在水中，使水也带着香气</li><li>茅舍：茅草屋</li><li>断桥：残破的桥</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>夕阳西下，酒旗悠闲地飘动，两三只渔船还没有靠岸。落花飘落在水中散发着香气，茅舍笼罩在暮色中，断桥头的鱼市已经散去。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首小令是马致远&quot;潇湘八景&quot;组曲之一，描绘了一幅宁静的渔村晚景图，是元曲中写景抒情的佳作。</p><p>&quot;夕阳下，酒旆闲&quot;，开篇就勾勒出一幅宁静的傍晚景象。夕阳西下，酒旗悠闲地飘动，&quot;闲&quot;字既写出了酒旗的状态，也暗示了渔村生活的宁静悠闲。</p><p>&quot;两三航未曾着岸&quot;，写远处还有几只渔船没有归港。&quot;两三&quot;二字，既写出了渔船之少，也增添了画面的空灵感。</p><p>&quot;落花水香茅舍晚&quot;，写渔村的环境。落花飘落在水中，使水也带着香气，茅草屋笼罩在暮色中。这一句从嗅觉、视觉角度描绘渔村的景色，营造出一种清幽的意境。</p><p>&quot;断桥头卖鱼人散&quot;，写鱼市已散，人们各自归家。&quot;断桥&quot;增添了画面的古朴感，&quot;卖鱼人散&quot;则暗示了渔村生活的规律和平静。</p><p>全曲语言凝练，意境清幽，将渔村的宁静生活描绘得如诗如画，体现了马致远散曲清新自然的风格。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>马致远</strong>（约1250年－约1321年），号东篱，元代著名戏曲作家、散曲家，元曲四大家之一。其散曲风格豪放洒脱，意境深远。</p><p><a href="/authors/mazhiyuan.html">查看作者详情 →</a></p></blockquote>',18)),u(t)])}const b=o(n,[["render",s]]);export{_ as __pageData,b as default};
